import openpyxl

def get_green_cells(file_path):
    wb = openpyxl.load_workbook(file_path)
    ws = wb.active
    greens = []
    for row in ws.iter_rows():
        for cell in row:
            f = cell.fill
            if f and f.fgColor and f.fgColor.type == 'rgb':
                if f.fgColor.rgb in ['FF00FF00','FF008000','FF00FF99']:
                    greens.append((cell.row, cell.column))
    return greens

